import sys

if len(sys.argv) < 4:
    print("Kullanım: python hesap.py <sayı> <işlem> <sayı>")
    sys.exit(1)

a = float(sys.argv[1])
b = float(sys.argv[2])
opr = sys.argv[3]

if opr == '+':
    print(a + b)
elif opr == '-':
    print(a - b)
elif opr == '*':
    print(a * b)
elif opr == '/':
    if b == 0:
        print('Hata: Sıfıra bölünme')
    else:
        print(a / b)

